-- specforge -- checks a project and builds its Markdown and PDF.
--
-- LuaLaTeX runs in a fresh temporary folder that holds only generated files,
-- the framework's template and the checked figures. Nothing else in the
-- project (a stray .sty file, for example) can take part in the build.

return function(U, P, S, M, F)
  local B = {}

  local MONTHS = { "January", "February", "March", "April", "May", "June", "July",
    "August", "September", "October", "November", "December" }

  local function today()
    local t = os.date("*t")
    return string.format("%d %s %d", t.day, MONTHS[t.month], t.year)
  end

  local function md_cell(s) return (tostring(s):gsub("|", "\\|")) end

  local function front_matter(p, v, date)
    local out = {}
    local function add(s) out[#out + 1] = s end
    if v["front_matter.document_information"] then
      add("## Document Information")
      add("")
      add("| Item | Value |")
      add("|---|---|")
      local function row(k, x) add("| " .. k .. " | " .. md_cell(x) .. " |") end
      row("Document type", p.subtitle)
      row("Design", p.title)
      row("Revision", p.revision)
      row("Date", date)
      row("Author", p.author)
      if p.organization ~= "" then row("Organization", p.organization) end
      row("Status", p.status)
      for _, r in ipairs(p.related) do row("Related document", r) end
      add("")
    end
    if v["front_matter.revision_history"] then
      local file = p.dir .. "/revision-history.md"
      if not U.is_file(file) then U.fail("revision-history.md is missing (copy templates/revision-history.md)") end
      local rows = {}
      for _, line in ipairs(U.split(U.read(file), "\n")) do
        if line:match("^|") then rows[#rows + 1] = line elseif #rows > 0 then break end
      end
      if #rows < 3 then U.fail("revision-history.md: no revision table found") end
      add("## Revision History")
      add("")
      for _, r in ipairs(rows) do add(r) end
      add("")
    end
    return out
  end

  local function metadata(p, date)
    local out = { "% GENERATED by specforge from project.md" }
    for _, e in ipairs({
      { "Title", p.title }, { "ShortTitle", p.short_name }, { "Subtitle", p.subtitle }, { "Author", p.author },
      { "Organization", p.organization }, { "Revision", p.revision }, { "Date", date },
      { "Status", p.status }, { "Language", p.language },
    }) do
      out[#out + 1] = "\\newcommand{\\Doc" .. e[1] .. "}{" .. U.tex(e[2]) .. "}"
    end
    return table.concat(out, "\n") .. "\n"
  end

  local function title_fields(p, v)
    local known = U.set({ "Author", "Organization", "Revision", "Date", "Status" })
    local out = {}
    for _, f in ipairs(v["title_page.fields"]) do
      if not known[f] then U.fail("title_page.fields: unknown field '%s'", tostring(f)) end
      if f ~= "Organization" or p.organization ~= "" then out[#out + 1] = f .. " & \\Doc" .. f end
    end
    -- no row end after the last row: it would add an empty row
    return table.concat(out, " \\\\\n") .. "\n"
  end

  local function anchor(title)
    local s = title:lower():gsub("\226\128[\128-\191]", "")
    s = s:gsub("[^%w _%-\128-\255]", "")
    return (s:gsub(" ", "-"))
  end

  local function combined_markdown(p, front, chapters)
    local rel = U.relative(p.out_dir, p.dir .. "/figures"):gsub("%%", "%%%%")
    local out = {
      "<!-- GENERATED by specforge from the project's chapter files. Do not edit by hand. -->",
      "", "# " .. p.title .. " \226\128\148 " .. p.subtitle, "",
    }
    for _, l in ipairs(front) do out[#out + 1] = l end
    out[#out + 1] = "## Table of Contents"
    out[#out + 1] = ""
    for _, c in ipairs(chapters) do
      for _, line in ipairs(U.split(c.text, "\n")) do
        local hashes, title = line:match("^(##?) (.+)$")
        if hashes then
          title = U.trim(title)
          out[#out + 1] = (#hashes == 1 and "" or "  ") .. "- [" .. title:gsub("`", "") .. "](#" .. anchor(title) .. ")"
        end
      end
    end
    for _, c in ipairs(chapters) do
      out[#out + 1] = ""
      out[#out + 1] = "---"
      out[#out + 1] = ""
      out[#out + 1] = (c.text:gsub("%s+$", ""):gsub("%]%(%.%./figures/", "](" .. rel .. "/"))
    end
    return (table.concat(out, "\n"):gsub("%s+$", "")) .. "\n"
  end

  local function checked_figures(p, used)
    local dir = p.dir .. "/figures"
    local names, have, problems = {}, {}, {}
    for _, file in ipairs(U.list(dir, "%.tex$")) do
      local name = file:gsub("%.tex$", "")
      if not name:match("^[%w%-]+$") then
        problems[#problems + 1] = "figures/" .. file .. ": a figure name has only letters, digits and hyphens"
      else
        local text = U.read(dir .. "/" .. file)
        for _, msg in ipairs(F.check(text, "figures/" .. file)) do problems[#problems + 1] = msg end
        names[#names + 1] = { name = name, text = text }
        have[name] = true
      end
    end
    for _, f in ipairs(used) do
      if not have[f.name] then problems[#problems + 1] = f.where .. ": figures/" .. f.name .. ".tex does not exist" end
    end
    if #problems > 0 then U.fail("figure check failed:\n  " .. table.concat(problems, "\n  ")) end
    return names
  end

  -- Everything that needs no TeX run.
  function B.prepare(root, dir)
    local p = P.load(root, dir, true)
    local build = dir .. "/build"
    U.mkdir(build)

    local style = S.make(root, dir)
    U.write(build .. "/style-report.md", style.files["style-report.md"])
    if #style.failed > 0 then
      U.fail("contrast check failed (colour-guide.md Section 3.2): %s. See build/style-report.md", table.concat(style.failed, "; "))
    end
    U.say(style.summary)

    local date = p.date or today()
    local front = front_matter(p, style.value, date)
    local conv = M.converter(style.value)
    local front_tex = conv.convert(table.concat(front, "\n") .. "\n", "front matter", true)

    local files = U.list(dir .. "/chapters", "^%d%d_.*%.md$")
    local chapters, body = {}, { "% GENERATED by specforge" }
    for _, name in ipairs(files) do
      if not name:match("^00_") then
        local c = { name = name, text = U.read(dir .. "/chapters/" .. name) }
        chapters[#chapters + 1] = c
        body[#body + 1] = "% ---- generated from chapters/" .. name .. " ----"
        for _, l in ipairs(conv.convert(c.text, name, false, #chapters)) do body[#body + 1] = l end
      end
    end
    if #chapters == 0 then U.fail("no chapter files (chapters/NN_name.md) yet") end
    U.say(string.format("Converted %d chapter file(s) and the front matter.", #chapters))
    conv.check_refs()

    local figures = checked_figures(p, conv.figures)

    local gen = {
      ["sf-class.tex"] = style.files["sf-class.tex"],
      ["sf-config.tex"] = style.files["sf-config.tex"],
      ["sf-setup.tex"] = style.files["sf-setup.tex"],
      ["sf-metadata.tex"] = metadata(p, date),
      ["sf-titlefields.tex"] = title_fields(p, style.value),
      ["sf-front.tex"] = "% GENERATED by specforge\n" .. table.concat(front_tex, "\n") .. "\n",
      ["sf-body.tex"] = table.concat(body, "\n") .. "\n",
    }
    for name, text in pairs(gen) do U.write(build .. "/" .. name, text) end

    if p.combined then
      local path = p.out_dir .. "/" .. p.file_name .. ".md"
      U.write(path, combined_markdown(p, front, chapters))
      U.say("Wrote " .. path)
    end
    return { project = p, gen = gen, figures = figures, build = build }
  end

  local function stage(root, job, work)
    for name, text in pairs(job.gen) do U.write(work .. "/build/" .. name, text) end
    local template = root .. "/latex/template"
    U.copy(template .. "/main.tex", work .. "/build/main.tex")
    for _, name in ipairs(U.list(template .. "/preamble", "%.tex$")) do
      U.copy(template .. "/preamble/" .. name, work .. "/build/sf/" .. name)
    end
    U.copy(root .. "/latex/tikz/sf-tikz.tex", work .. "/build/sf/tikz.tex")
    for _, f in ipairs(job.figures) do U.write(work .. "/figures/" .. f.name .. ".tex", f.text) end
  end

  local function lualatex(job, work, name)
    local exe = U.which("lualatex")
    if not exe then U.fail("lualatex not found: run 'specforge doctor'") end
    local code = U.run(exe, { "-no-shell-escape", "-interaction=batchmode", "-halt-on-error",
      "-output-directory=build", "build/" .. name .. ".tex" }, work)
    local log_file = work .. "/build/" .. name .. ".log"
    local log = U.is_file(log_file) and U.read_bytes(log_file) or ""
    U.write(job.build .. "/" .. name .. ".log", log)
    if code ~= 0 then
      local lines, shown = U.split((log:gsub("\r", "")), "\n"), {}
      for i, line in ipairs(lines) do
        if line:match("^!") then
          for j = i, math.min(i + 6, #lines) do shown[#shown + 1] = "  " .. lines[j] end
          break
        end
      end
      U.fail("lualatex failed; see build/%s.log\n%s", name, table.concat(shown, "\n"))
    end
    return log
  end

  local function export_figures(job, work)
    if #job.figures == 0 then U.say("No figure sources in figures/."); return end
    local exe = U.which("pdftocairo")
    if not exe then
      U.warn("pdftocairo not found: figure previews skipped (the PDF is not affected); install poppler")
      return
    end
    local tex = { "% GENERATED by specforge -- one figure per page, in name order." }
    for _, f in ipairs({ "sf-config", "sf-metadata", "sf-class", "sf/packages", "sf-setup",
      "sf/typography", "sf/tables", "sf/tikz", "sf/macros" }) do
      tex[#tex + 1] = "\\input{build/" .. f .. "}"
    end
    tex[#tex + 1] = "\\usepackage[active,tightpage]{preview}"
    tex[#tex + 1] = "\\setlength{\\PreviewBorder}{6pt}"
    tex[#tex + 1] = "\\pagestyle{empty}"
    tex[#tex + 1] = "\\begin{document}"
    for _, f in ipairs(job.figures) do
      tex[#tex + 1] = "\\begin{preview}\\begin{varwidth}{\\textwidth}"
        .. (M.is_timing(f.name) and "\\justifying" or "\\centering")
        .. "\\input{figures/" .. f.name .. "}\\end{varwidth}\\end{preview}"
    end
    tex[#tex + 1] = "\\end{document}"
    U.write(work .. "/build/figure-export.tex", table.concat(tex, "\n") .. "\n")
    lualatex(job, work, "figure-export")
    for i, f in ipairs(job.figures) do
      local out = "figures/" .. f.name .. ".svg"
      local code = U.run(exe, { "-svg", "-f", tostring(i), "-l", tostring(i), "build/figure-export.pdf", out }, work)
      if code ~= 0 then U.fail("pdftocairo failed on figure %s", f.name) end
      U.copy(work .. "/" .. out, job.project.dir .. "/" .. out)
      U.say(out)
    end
  end

  local function report(job, log)
    local p, count = job.project, 0
    for line in log:gmatch("[^\r\n]+") do
      if line:find("Overfull", 1, true) or line:find("Underfull \\hbox (badness 10000", 1, true)
        or line:find("undefined", 1, true) or line:find("multiply defined", 1, true)
        or line:find("Missing character", 1, true) then
        count = count + 1
        U.warn(line)
      end
    end
    if count == 0 then U.say("Clean build: no overfull boxes, undefined references or missing characters.") end
    local pages = tonumber(log:gsub("[\r\n]", ""):match("Output written on .-%((%d+) page"))
    if not pages then return end
    local budget = string.format("(budget %d to %d)", p.min_pages, p.max_pages)
    if pages > p.max_pages then U.warn(pages .. " pages: above the page budget " .. budget .. ".")
    elseif pages < p.min_pages then U.say(pages .. " pages: below the page budget " .. budget .. " -- check that nothing is missing.")
    else U.say(pages .. " pages " .. budget .. ".") end
  end

  -- opts.figures: export SVG previews; opts.pdf: compile the document.
  function B.run(root, dir, opts)
    local job = B.prepare(root, dir)
    if not opts.figures then
      for _, f in ipairs(job.figures) do
        local svg, src = dir .. "/figures/" .. f.name .. ".svg", dir .. "/figures/" .. f.name .. ".tex"
        if not U.is_file(svg) or U.mtime(svg) < U.mtime(src) then
          U.warn("figures/" .. f.name .. ".svg is missing or older than its source: build with --figures")
        end
      end
      if not opts.pdf then return end
    end

    local work = U.tempdir()
    local ok, err = pcall(function()
      stage(root, job, work)
      if opts.figures then export_figures(job, work) end
      if opts.pdf then
        local log
        for _ = 1, 3 do log = lualatex(job, work, "main") end
        report(job, log)
        local out = job.project.out_dir .. "/" .. job.project.file_name .. ".pdf"
        U.copy(work .. "/build/main.pdf", out)
        U.say("Wrote " .. out)
      end
    end)
    U.remove_tempdir(work)
    if not ok then error(err, 0) end
  end

  return B
end
